/** Deterministic TEST-only bundle. Historical migration files remain untouched. */
import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
const root=new URL('../../',import.meta.url);
const read=p=>readFileSync(new URL(p,root),'utf8');
const sha=s=>createHash('sha256').update(s).digest('hex');
const take=(s,start,end)=>{const a=s.indexOf(start),b=s.indexOf(end,a+start.length);if(a<0||b<0)throw Error('Import prerequisite source boundaries differ');return s.slice(a,b);};
export function buildImportBundle(){
 const files=['20260828120000_marketing_foundation.sql','20260829120000_marketing_contacts_projection.sql','20260912120000_commusoft_governed_import.sql','20260929120000_contact_point_primary_fix.sql','20260930120000_exact_job_site_resolution.sql','20261029170000_learn_import_boundaries.sql'];
 const sources=Object.fromEntries(files.map(n=>[n,read('supabase/migrations/'+n)]));
 let contact=take(sources[files[0]],'create table if not exists contact_points (','-- ===========================================================================\n-- contact_relationships');
 contact=contact.replace('create table if not exists contact_points','create table contact_points');
 // No draft-object removal or IF NOT EXISTS may conceal a collision in TEST.
 contact=contact.replace(/drop (?:index|trigger) if exists [^;]+;\n/g,'').replaceAll('index if not exists','index');
 const normalizer=take(sources[files[1]],'create or replace function marketing_normalize_endpoint(', '-- ===========================================================================\n-- marketing_identity_conflicts');
 const prerequisites=`create unique index data_imports_tenant_id_uk on public.data_imports(tenant_id,id);
create unique index people_tenant_id_uk on public.people(tenant_id,id);
${contact}
alter table public.contact_points add constraint contact_points_person_tenant_fk foreign key(tenant_id,person_id) references public.people(tenant_id,id) on delete cascade;
alter table public.contact_points enable row level security;
create policy contact_points_select_tenant on public.contact_points for select to authenticated using(tenant_id=public.current_tenant_id());
revoke all on public.contact_points from public,anon,authenticated;
grant select on public.contact_points to authenticated;
grant select,insert,update,delete on public.contact_points to service_role;
revoke truncate on public.contact_points from service_role;
${normalizer}
revoke all on function public.marketing_normalize_endpoint(text,text) from public,anon,authenticated;
grant execute on function public.marketing_normalize_endpoint(text,text) to service_role;
`;
 const body=prerequisites+files.slice(2).map(n=>`\n-- SOURCE ${n}; SHA-256 ${sha(sources[n])}\n${sources[n]}`).join('\n');
 const functions=[...new Set([...body.matchAll(/create or replace function (?:public\.)?(\w+)\(/gi)].map(m=>m[1]))].sort();
 const relations=['contact_points','import_entity_links','import_conflicts','import_row_results','data_imports_tenant_id_uk','people_tenant_id_uk'];
 const sql=`-- Generated by scripts/verify/learn-import-bundle.mjs. TEST only; no real import.
begin;
set local search_path=public,pg_temp;
set local lock_timeout='3s';
set local statement_timeout='30s';
lock table of_test_deploy.migrations in share row exclusive mode;
do $$ declare n text;begin
 if current_setting('serviceos.release_target',true) is distinct from 'saatxzwxvdvqevbnskxy' or coalesce(current_setting('serviceos.release_source_sha256',true),'') !~ '^[a-f0-9]{64}$' then raise exception 'Explicit TEST target and reviewed checksum required';end if;
 if (select count(*) from of_test_deploy.migrations)<>22 or not exists(select 1 from of_test_deploy.migrations where migration_name='learn_slack_thread_recovery_v1' and source_sha256='16d639506c5a7626b6cc3563798b44303e8cf922c9d776e6752c1c80fcd03344' and project_ref='saatxzwxvdvqevbnskxy') then raise exception 'Exact TEST thread recovery prerequisite required';end if;
 foreach n in array array[${relations.map(n=>`'${n}'`).join(',')}] loop
  if to_regclass('public.'||quote_ident(n)) is not null then raise exception 'Import prerequisite object already exists';end if;
 end loop;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[${functions.map(n=>`'${n}'`).join(',')}])) then raise exception 'Import function already exists';end if;
 if exists(select 1 from public.import_profiles where source_system='commusoft' and name in ('Commusoft Prepared Customers','Commusoft Prepared Sites','Commusoft Prepared Jobs')) then raise exception 'Prepared import profile already exists';end if;
end $$;
${body}
-- Explicitly bound privileges, including the two trigger helpers omitted from
-- the original function-grant loop. Default database grants are not authority.
do $$ declare f record;begin
 for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[${functions.map(n=>`'${n}'`).join(',')}]) loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $$;
insert into of_test_deploy.migrations(source_sha256,migration_name,project_ref,applied_at) values(current_setting('serviceos.release_source_sha256'),'learn_governed_imports_v1','saatxzwxvdvqevbnskxy',clock_timestamp());
commit;
`;
 return {sql,manifest:{version:'learn-governed-imports-bundle/1',sha256:sha(sql),sources:Object.fromEntries(files.map(n=>[n,sha(sources[n])])),functions,tables:['contact_points','import_entity_links','import_conflicts','import_row_results'],existingTableIndexes:['data_imports_tenant_id_uk','people_tenant_id_uk'],limitations:['TEST dependency recovery only. Existing hosted data and original migrations are not rewritten.','Only the historical endpoint primitive/normalizer is recovered from marketing; no marketing permission or sending machinery is enabled.','Deployment and actual Auth/Edge/UI acceptance remain separate gates.']}};
}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){
 if(process.argv.slice(2).join(' ')!=='--write')throw Error('Use --write to produce the local reviewable TEST bundle');
 const b=buildImportBundle();writeFileSync(new URL('supabase/release/learn-test/022_governed_imports.sql',root),b.sql);writeFileSync(new URL('supabase/release/learn-test/022_governed_imports.manifest.json',root),JSON.stringify(b.manifest,null,2)+'\n');console.log(JSON.stringify({sha256:b.manifest.sha256,functions:b.manifest.functions.length,tables:b.manifest.tables.length}));
}
